const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const bytes=async b=>Array.from(new Uint8Array(await b.arrayBuffer())).join(',');
test('body-byte-sources',async()=>{for(const data of [[255,0,128],[195,169],[239,187,191,120]])for(const raw of [true,false]){const value=new Uint8Array(data),r=new Response(raw?value.buffer:value);log(raw,await bytes(r))}});
test('body-blob-sources',async()=>{const b=new Blob([new Uint8Array([255,0,128])]);for(const r of [new Response(b),new Request('https://app.example/upload',{method:'POST',body:b})])log(await bytes(r))});
test('body-clone-snapshots',async()=>{const data=new Uint8Array([255,0,128]),r=new Response(data),copy=r.clone();data[0]=1;log(await bytes(r),await bytes(copy));const q=new Request('https://app.example/upload',{method:'POST',body:new Uint8Array([255,0,128])}),qc=q.clone();log(await bytes(q),await bytes(qc))});
test('body-text-bom',async()=>{for(const data of ['\ufeffhello',new Uint8Array([239,187,191,104,105])])log(JSON.stringify(await new Response(data).text()));log((await new Response('\ufeff{"n":1}').json()).n)});
test('body-response-blob-type',async()=>{for(const contentType of ['TEXT/PLAIN; Charset=UTF-8','application/octet-stream','invalid']){const b=await new Response(new Uint8Array([255,0,128]),{headers:{'Content-Type':contentType}}).blob();log(b.type,b.size,await bytes(b))}});
test('body-promise-brands',async()=>{for(const kind of [Response,Request])for(const name of ['text','arrayBuffer','json','blob'])try{const p=kind.prototype[name].call({});log(kind.name,name,'promise',p instanceof Promise);await p;log('accepted')}catch(e){log(kind.name,name,e.name)}});
test('body-view-range',async()=>{const b=new Uint8Array([9,255,0,128,9]).buffer;for(const value of [new Uint8Array(b,1,3),new DataView(b,1,3)])log(await bytes(new Response(value)))});
test('body-option-mutation',async()=>{const data=new Uint8Array([1,2]),r=new Response(data,{get headers(){data[0]=9;return []}});data[1]=8;log(await bytes(r));const other=new Uint8Array([1,2]),q=new Request('https://app.example/upload',{method:'POST',body:other,get headers(){other[0]=9;return []}});other[1]=8;log(await bytes(q))});
test('body-cross-brands',async()=>{for(const [target,source] of [[Response,new Request('https://app.example/',{method:'POST',body:'q'})],[Request,new Response('r')]])try{log(target.name,await target.prototype.text.call(source))}catch(e){log(target.name,e.name)}});
test('body-buffer-validation',async()=>{for(const which of ['buffer','typed','view']){const b=new ArrayBuffer(2),v=which==='buffer'?b:which==='typed'?new Uint8Array(b):new DataView(b);structuredClone(b,{transfer:[b]});try{log('detached',which,await bytes(new Response(v)))}catch(e){log('detached',which,e.name)}const r=new ArrayBuffer(2,{maxByteLength:4}),part=which==='buffer'?r:which==='typed'?new Uint8Array(r):new DataView(r);let count=0;try{const response=new Response(part,{get headers(){count++;return []}});log('resizable',which,await bytes(response),count)}catch(e){log('resizable',which,e.name,count)}}});
test('body-response-mime',async()=>{for(const type of ['TeXt/Plain ; X="A B"; charset=UTF-8','text/plain; x=a; x=b','text/plain; x="a\\b"','text/plain; x="é"','*/*','text/plain;empty=','text/plain;charset="UTF-8"','invalid']){try{const b=await new Response('x',{headers:{'content-type':type}}).blob();log(JSON.stringify(type),JSON.stringify(b.type))}catch(e){log(JSON.stringify(type),e.name)}}});
test('body-response-init',()=>{for(const status of [200,201.9,0,65536+201,Infinity,null,1n])try{const r=new Response(null,{status});log(typeof status,String(status),r.status,r.type)}catch(e){log(typeof status,String(status),e.name)}for(const statusText of ['OK','a\tb','a\nb','a\0b','é','€'])try{const r=new Response(null,{statusText});log(JSON.stringify(statusText),JSON.stringify(r.statusText))}catch(e){log(JSON.stringify(statusText),e.name)}for(const status of [204,205,304])try{new Response('x',{status});log(status,'accepted')}catch(e){log(status,e.name)}});
test('body-private-header-arrays',async()=>{const define=Object.defineProperty;let calls=0,result;define(Array.prototype,'0',{configurable:true,set(value){define(this,'0',{value,writable:true,enumerable:true,configurable:true});calls++}});try{const headers=new Headers([['X','v']]);headers.append('Y','w');const response=new Response('x',{headers});result=headers.get('x')+' '+response.headers.get('y')+' '+await response.text()}finally{delete Array.prototype[0]}log(result,calls)});
